using System;
using System.IO;
using System.Net;

namespace UI_Desktop.Store;

internal static class StoreSupportContactHeaderHtml
{
	private static class Icons
	{
		internal static readonly string Headset = Read("SupportContact", "headset");

		internal static readonly string Phone = Read("SupportContact", "telephone");

		internal static readonly string Copy = Read("SupportContact", "copy");

		internal static readonly string Chevron = Read("SteamConnection", "chevron-down");

		internal static readonly string Close = Read("SteamConnection", "x-lg");

		internal static readonly string Open = Read("SteamConnection", "box-arrow-up-right");

		private static string Read(string group, string name)
		{
			using Stream stream = typeof(StoreSupportContactHeaderHtml).Assembly.GetManifestResourceStream($"NestG.{group}.Icons.{name}.svg") ?? throw new InvalidOperationException("Missing bundled support icon: " + name);
			using MemoryStream memoryStream = new MemoryStream();
			stream.CopyTo(memoryStream);
			return "data:image/svg+xml;base64," + Convert.ToBase64String(memoryStream.ToArray());
		}
	}

	internal static string Styles => ".nestg-support-contact { display:inline-flex; flex:0 0 auto; }\n.nestg-support-contact .nestg-contact-trigger { display:inline-flex; align-items:center; justify-content:center; gap:8px; height:36px; padding:0 12px; border:1px solid #344b62; border-radius:6px; background:linear-gradient(135deg,#182431,#223248); color:#d8eaff; font:600 13px \"Segoe UI\",sans-serif; white-space:nowrap; cursor:pointer; transition:background .15s,border-color .15s; }\n.nestg-support-contact .nestg-contact-trigger:hover, .nestg-support-contact .nestg-contact-trigger[aria-expanded=\"true\"] { border-color:#83bdf1; background:#233951; }\n.nestg-contact-icon { display:inline-block; width:20px; height:20px; flex:0 0 auto; background:currentColor; -webkit-mask:var(--nestg-contact-icon) center/contain no-repeat; mask:var(--nestg-contact-icon) center/contain no-repeat; }\n.nestg-contact-trigger .nestg-contact-icon { width:18px; height:18px; color:#9bcefa; }\n.nestg-contact-trigger .nestg-contact-chevron { width:12px; height:12px; transition:transform .15s; }\n.nestg-contact-trigger[aria-expanded=\"true\"] .nestg-contact-chevron { transform:rotate(180deg); }\n.nestg-contact-panel, .nestg-contact-panel * { box-sizing:border-box; }\n.nestg-contact-panel { position:fixed; z-index:600; width:400px; padding:20px; border:1px solid #56768d; border-radius:12px; background:linear-gradient(135deg,#1b2733,#151f29); color:#f1f5fb; font:14px/1.5 \"Segoe UI\",sans-serif; box-shadow:0 16px 40px #0009; overflow-y:auto; overscroll-behavior:contain; color-scheme:dark; }\n.nestg-contact-panel[hidden], .nestg-contact-panel [hidden] { display:none !important; }\n.nestg-contact-panel::before { content:\"\"; position:fixed; width:14px; height:14px; left:calc(var(--nestg-contact-arrow-x,32px) - 7px); top:calc(var(--nestg-contact-arrow-y,48px) - 7px); background:#1b2733; border-top:1px solid #56768d; border-left:1px solid #56768d; transform:rotate(45deg); pointer-events:none; }\n.nestg-contact-heading { display:flex; align-items:center; gap:12px; }\n.nestg-contact-heading > .nestg-contact-icon { width:24px; height:24px; color:#87c4ff; }\n.nestg-contact-panel h2, .nestg-contact-panel h3, .nestg-contact-panel p { margin:0; }\n.nestg-contact-panel h2 { font-size:20px; line-height:1.3; font-weight:700; }\n.nestg-contact-panel .nestg-contact-close { display:inline-grid; place-items:center; width:32px; height:32px; margin:-4px -4px -4px auto; padding:0; border:0; border-radius:6px; background:transparent; color:#becddb; cursor:pointer; }\n.nestg-contact-panel .nestg-contact-close:hover { background:#ffffff12; color:#fff; }\n.nestg-contact-panel .nestg-contact-description { margin-top:10px; color:#b2c8dd; }\n.nestg-contact-zalo { display:grid; grid-template-columns:152px minmax(0,1fr); align-items:center; gap:20px; margin-top:20px; }\n.nestg-contact-qr { display:grid; place-items:center; width:152px; height:152px; padding:8px; border-radius:9px; background:#fff; }\n.nestg-contact-qr img { display:block; width:100%; height:100%; object-fit:contain; }\n.nestg-contact-qr-missing { color:#24354a; font-size:13px; text-align:center; }\n.nestg-contact-panel h3 { font-size:17px; font-weight:700; }\n.nestg-contact-zalo-copy > p { margin:8px 0 16px; color:#b2c8dd; }\n.nestg-contact-panel .nestg-contact-open, .nestg-contact-panel .nestg-contact-copy { display:inline-flex; align-items:center; justify-content:center; gap:8px; min-height:38px; padding:8px 12px; border:1px solid #6aaef0; border-radius:7px; color:#f8fbff; font:600 14px \"Segoe UI\",sans-serif; white-space:nowrap; cursor:pointer; }\n.nestg-contact-panel .nestg-contact-open { width:100%; background:linear-gradient(135deg,#3582d1,#419dea); }\n.nestg-contact-panel .nestg-contact-open:hover { background:#388dd9; }\n.nestg-contact-panel .nestg-contact-copy { background:#1b2b3c; border-color:#496b8a; }\n.nestg-contact-panel .nestg-contact-copy:hover { border-color:#87c4ff; background:#233b52; }\n.nestg-contact-phone-row { display:flex; align-items:center; gap:12px; margin-top:20px; padding-top:16px; border-top:1px solid #34485b; }\n.nestg-contact-phone-row > .nestg-contact-icon { width:24px; height:24px; }\n.nestg-contact-phone { display:flex; flex-direction:column; min-width:0; flex:1; gap:3px; }\n.nestg-contact-phone > span { color:#b2c8dd; font-size:12px; }\n.nestg-contact-phone > input { display:block; width:100%; min-width:0; padding:0; border:0; border-radius:2px; background:transparent; color:#f1f5fb; font:700 18px \"Segoe UI\",sans-serif; user-select:text; cursor:text; }\n.nestg-contact-panel .nestg-contact-feedback { margin-top:12px; color:#b2c8dd; font-size:13px; }\n.nestg-contact-panel button:disabled { opacity:.65; cursor:wait; }\n.nestg-contact-panel button:focus-visible, .nestg-support-contact button:focus-visible, .nestg-contact-phone input:focus-visible { outline:2px solid #87c4ff; outline-offset:2px; }\n.nestg-header-account:has(.nestg-support-contact) { display:flex; align-items:center; gap:10px; }\n@media (max-width:1180px) { .nestg-contact-trigger-label, .nestg-contact-trigger .nestg-contact-chevron { display:none; } .nestg-support-contact .nestg-contact-trigger { width:36px; padding:0; } }\n@media (max-width:980px) { .top-chrome:has(.nestg-support-contact) .user-chip > span:nth-child(2), .top-chrome:has(.nestg-support-contact) .nestg-warp-label { display:none; } }\n@media (max-width:680px) { .top-chrome .utility-row:has(.nestg-support-contact) { grid-template-columns:minmax(0,1fr); height:auto; gap:6px; padding-block:6px; } .top-chrome:has(.nestg-support-contact) .utility-right { width:100%; justify-content:space-between; } }\n@media (max-width:520px) { .nestg-header-account:has(.nestg-support-contact) { gap:6px; } .nestg-contact-panel { padding:16px; } .nestg-contact-zalo { grid-template-columns:136px minmax(0,1fr); gap:12px; margin-top:16px; } .nestg-contact-qr { width:136px; height:136px; } .nestg-contact-panel .nestg-contact-open, .nestg-contact-panel .nestg-contact-copy { padding-inline:8px; font-size:13px; } .nestg-contact-phone-row { gap:8px; } .nestg-contact-phone-row > .nestg-contact-icon { width:20px; } .nestg-contact-phone > input { font-size:17px; } }\n@media (max-width:520px) { .profile-chrome:has(.nestg-support-contact) .brand-copy, .orders-chrome:has(.nestg-support-contact) .brand-copy, .wallet-chrome:has(.nestg-support-contact) .brand-copy { display:none; } }\n@media (prefers-reduced-motion:reduce) { .nestg-contact-trigger, .nestg-contact-chevron { transition:none !important; } }";

	internal static string Script => "(() => {\n    const documentId = globalThis.crypto?.randomUUID?.() ?? (Date.now().toString(36) + Math.random().toString(36));\n    let control, trigger, panel, pending, timer;\n    const feedback = text => {\n        const node = panel?.querySelector('[data-support-contact-feedback]');\n        if (node) { node.textContent = text || ''; node.hidden = !text; }\n    };\n    const position = () => {\n        if (!panel || panel.hidden) return;\n        const anchor = trigger.getBoundingClientRect();\n        const viewport = window.visualViewport;\n        const width = Math.min(innerWidth, viewport?.width ?? innerWidth);\n        const height = Math.min(innerHeight, viewport?.height ?? innerHeight);\n        const top = Math.max(8, Math.min(anchor.bottom + 12, height - 120));\n        panel.style.maxWidth = Math.max(0, width - 16) + 'px';\n        panel.style.maxHeight = Math.max(0, height - top - 8) + 'px';\n        panel.style.top = top + 'px';\n        const panelWidth = panel.getBoundingClientRect().width;\n        const left = Math.max(8, Math.min(anchor.left, width - panelWidth - 8));\n        panel.style.left = left + 'px';\n        panel.style.setProperty('--nestg-contact-arrow-x', Math.max(left + 20, Math.min(left + panelWidth - 20, anchor.left + anchor.width / 2)) + 'px');\n        panel.style.setProperty('--nestg-contact-arrow-y', top + 'px');\n    };\n    const resetPending = () => {\n        clearTimeout(timer);\n        if (pending) pending.button.disabled = false;\n        pending = null;\n    };\n    const close = restoreFocus => {\n        if (!panel || panel.hidden) return;\n        panel.hidden = true;\n        trigger.setAttribute('aria-expanded', 'false');\n        resetPending();\n        if (restoreFocus && trigger.isConnected) trigger.focus();\n    };\n    const completeAction = result => {\n        if (!pending || result?.documentId !== documentId || result.requestId !== pending.requestId) return;\n        const type = pending.type;\n        resetPending();\n        feedback(result.message);\n        if (type === 'copySupportPhone') {\n            panel.querySelector('[data-support-contact-copy-label]').textContent = result.success ? 'Đã sao chép' : 'Sao chép';\n            if (!result.success && !panel.hidden) { const phone = panel.querySelector('[data-support-contact-phone]'); phone.focus(); phone.select(); }\n        }\n        position();\n    };\n    const request = button => {\n        if (pending) return;\n        if (!window.chrome?.webview?.postMessage) { feedback('Vui lòng mở chức năng này trong NestG Launcher.'); position(); return; }\n        const type = button.dataset.supportContactAction;\n        if (type === 'copySupportPhone') panel.querySelector('[data-support-contact-copy-label]').textContent = 'Sao chép';\n        const requestId = globalThis.crypto?.randomUUID?.() ?? (Date.now().toString(36) + Math.random().toString(36));\n        pending = {button, type, requestId};\n        button.disabled = true;\n        feedback(type === 'copySupportPhone' ? 'Đang sao chép…' : 'Đang mở Zalo…');\n        timer = setTimeout(() => completeAction({documentId, requestId, success:false, message:'Chưa nhận được phản hồi. Vui lòng thử lại.'}), 8000);\n        try { window.chrome.webview.postMessage({type, documentId, requestId}); }\n        catch { completeAction({documentId, requestId, success:false, message:'Chưa gửi được yêu cầu. Vui lòng thử lại.'}); }\n        position();\n    };\n    const bind = () => {\n        control = document.querySelector('[data-support-contact-control]');\n        trigger = control?.querySelector('[data-support-contact-toggle]');\n        panel = control?.querySelector('[data-support-contact-panel]');\n        if (!trigger || !panel) return;\n        // Portal keeps the popup outside native drag regions and header clipping.\n        document.body.append(panel);\n        control.addEventListener('pointerdown', event => event.stopPropagation());\n        control.addEventListener('mousedown', event => event.stopPropagation());\n        panel.addEventListener('pointerdown', event => event.stopPropagation());\n        panel.addEventListener('mousedown', event => event.stopPropagation());\n        trigger.addEventListener('click', () => {\n            if (!panel.hidden) { close(true); return; }\n            window.__nestgSteamConnection?.close();\n            panel.hidden = false;\n            trigger.setAttribute('aria-expanded', 'true');\n            feedback('');\n            panel.querySelector('[data-support-contact-copy-label]').textContent = 'Sao chép';\n            position();\n            panel.querySelector('[data-support-contact-close]').focus();\n        });\n        panel.querySelector('[data-support-contact-close]').addEventListener('click', () => close(true));\n        for (const button of panel.querySelectorAll('[data-support-contact-action]')) button.addEventListener('click', () => request(button));\n        document.addEventListener('pointerdown', event => {\n            if (!panel.hidden && !control.contains(event.target) && !panel.contains(event.target)) close(false);\n        }, true);\n        document.addEventListener('keydown', event => {\n            if (!panel.hidden && event.key === 'Escape') { event.preventDefault(); event.stopImmediatePropagation(); close(true); }\n        }, true);\n        // Nonmodal dialog: tabbing back to the launcher dismisses the popover.\n        document.addEventListener('focusin', event => {\n            if (!panel.hidden && !panel.contains(event.target) && !control.contains(event.target)) close(false);\n        });\n        window.addEventListener('resize', position);\n        window.addEventListener('scroll', position, true);\n        window.visualViewport?.addEventListener('resize', position);\n        window.addEventListener('pagehide', () => close(false), {once:true});\n    };\n    window.__nestgSupportContact = {documentId, completeAction, close:() => close(true)};\n    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bind, {once:true});\n    else bind();\n})();";

	internal static string Render()
	{
		string qrAssetUrl = StoreSupportContact.QrAssetUrl;
		string value = (string.IsNullOrEmpty(qrAssetUrl) ? "<span class=\"nestg-contact-qr-missing\">Mở Zalo để liên hệ hỗ trợ.</span>" : ("<img src=\"" + WebUtility.HtmlEncode(qrAssetUrl) + "\" width=\"152\" height=\"152\" alt=\"Mã QR Zalo hỗ trợ NestG\" />"));
		return $"<div class=\"nestg-support-contact\" data-support-contact-control>\n    <button type=\"button\" class=\"nestg-contact-trigger\" data-support-contact-toggle\n            aria-label=\"Hỗ trợ NestG\" title=\"Hỗ trợ NestG\" aria-haspopup=\"dialog\" aria-expanded=\"false\" aria-controls=\"nestg-support-contact-panel\">\n        {Icon(Icons.Headset)}<span class=\"nestg-contact-trigger-label\">Hỗ trợ</span>{Icon(Icons.Chevron, "nestg-contact-chevron")}\n    </button>\n    <section id=\"nestg-support-contact-panel\" class=\"nestg-contact-panel\" data-support-contact-panel\n             role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"nestg-contact-title\" aria-describedby=\"nestg-contact-description\" hidden>\n        <div class=\"nestg-contact-heading\">\n            {Icon(Icons.Headset)}<h2 id=\"nestg-contact-title\">Hỗ trợ NestG</h2>\n            <button type=\"button\" class=\"nestg-contact-close\" data-support-contact-close aria-label=\"Đóng hỗ trợ\">{Icon(Icons.Close)}</button>\n        </div>\n        <p id=\"nestg-contact-description\" class=\"nestg-contact-description\">Liên hệ khi bạn cần hỗ trợ.</p>\n        <div class=\"nestg-contact-zalo\">\n            <div class=\"nestg-contact-qr\">{value}</div>\n            <div class=\"nestg-contact-zalo-copy\">\n                <h3>Zalo hỗ trợ</h3>\n                <p>Quét mã để chat<br />với NestG</p>\n                <button type=\"button\" class=\"nestg-contact-open\" data-support-contact-action=\"openSupportZalo\">\n                    {Icon(Icons.Open)}<span>Mở Zalo</span>\n                </button>\n            </div>\n        </div>\n        <div class=\"nestg-contact-phone-row\">\n            {Icon(Icons.Phone)}\n            <label class=\"nestg-contact-phone\"><span>Số điện thoại</span>\n                <input type=\"text\" value=\"{"0947709029"}\" data-support-contact-phone readonly aria-label=\"Số điện thoại hỗ trợ NestG\" />\n            </label>\n            <button type=\"button\" class=\"nestg-contact-copy\" data-support-contact-action=\"copySupportPhone\">\n                {Icon(Icons.Copy)}<span data-support-contact-copy-label>Sao chép</span>\n            </button>\n        </div>\n        <p class=\"nestg-contact-feedback\" data-support-contact-feedback role=\"status\" aria-live=\"polite\" aria-atomic=\"true\" hidden></p>\n    </section>\n</div>";
	}

	private static string Icon(string uri, string extraClass = "")
	{
		return $"<span class=\"nestg-contact-icon {extraClass}\" style=\"--nestg-contact-icon:url('{uri}')\" aria-hidden=\"true\"></span>";
	}
}
